// (484 cases), ecdsa_secp256r1_sha256_p1363_test.json (262),
// ecdsa_secp256r1_sha512_test.json (554), ecdsa_secp256r1_sha512_p1363_test.json
// (332) and x25519_test.json (518). And changed: the JSON is rewritten as Nish
// source, each ECDSA test group's public key is listed once and each case names
// its group's key by index, and the per-case comments and flags are left out.
// Every case of every file is kept, and every value kept is as upstream wrote
// it. The ECDSA files have no case whose result is "acceptable"; x25519_test.json
// has 254, each with the one shared secret RFC 7748 gives, which is what
// `x25519` answers. `tests/link/crypto_p256` and `crypto_p256_f64` run the ECDSA
// cases, and `tests/link/crypto_x25519` and `crypto_x25519_f64` the X25519 ones.
//
// The X25519 cases live here rather than in a file of their own only because a
// new file carrying the notice above needs its own row in THIRD_PARTY_NOTICES.md,
// which the change that added them could not edit; a later change may move them.

/** One `EcdsaVerify` case: its id, its group's key, the expected result, and the message and signature in hex (DER or `r || s`, as each list says). */
export interface WycheproofEcdsaCase {
  // `number` rather than `i32`, so the file compiles in either number mode: a
  // bare literal in an object literal takes the mode's width.
  tcId: number;
  key: number;
  result: string;
  msg: string;
  sig: string;
}

